class EmailSender(ABC):
    @abstractmethod
    def send(self, to, body): ...


class SmtpEmailSender(EmailSender):
    def send(self, to, body):
        pass  # real network call


class FakeEmailSender(EmailSender):
    def __init__(self):
        self.sent_messages = []

    def send(self, to, body):
        self.sent_messages.append(f"{to}: {body}")

