class EmailSender {
public:
    virtual ~EmailSender() = default;
    virtual void send(const std::string& to, const std::string& body) = 0;
};

class SmtpEmailSender : public EmailSender {
public:
    void send(const std::string& to, const std::string& body) override { /* real network call */ }
};

class FakeEmailSender : public EmailSender {
public:
    std::vector<std::string> sentMessages;
    void send(const std::string& to, const std::string& body) override {
        sentMessages.push_back(to + ": " + body);
    }
};

