        LocalDate issuedOn = LocalDate.now(clock); // deterministic in tests

        emailSender.send(order.getCustomerEmail(),
            "Invoice for " + total + ", issued " + issuedOn);
    }

    double calculateTotal(double subtotal) {
        return subtotal * 1.18; // pure, tested on its own
    }
}

